1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	import org.springframework.samples.petclinic.rest.validation.IdentityKeyNormalizer;
12	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
13	
14	import java.time.LocalDate;
15	import java.time.Period;
16	import java.time.temporal.ChronoUnit;
17	import java.util.Collection;
18	import java.util.List;
19	
20	/**
21	 * Maps Owner & OwnerDto using Mapstruct
22	 */
23	@Mapper(uses = PetMapper.class)
24	public interface OwnerMapper {
25	
26	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
27	    @Mapping(target = "initials", expression = "java(initials(owner))")
28	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
29	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
30	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
31	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
32	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
33	    @Mapping(target = "locality", expression = "java(locality(owner))")
34	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
35	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarning(owner))")
36	    @Mapping(target = "possibleDuplicate", expression = "java(possibleDuplicate(owner))")
37	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
38	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
39	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
40	    OwnerDto toOwnerDto(Owner owner);
41	
42	    Owner toOwner(OwnerDto ownerDto);
43	
44	    /**
45	     * Formats an owner's stored names as {@code 'LastName, FirstName'}.
46	     */
47	    default String displayName(Owner owner) {
48	        if (owner == null) {
49	            return null;
50	        }
51	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
52	        String firstName = owner.getFirstName() == null ? "" : owner.getFirstName();
53	        return lastName + ", " + firstName;
54	    }
55	
56	    /**
57	     * Returns the upper-cased first letters of firstName and lastName,
58	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
59	     */
60	    default String initials(Owner owner) {
61	        if (owner == null) {
62	            return null;
63	        }
64	        StringBuilder sb = new StringBuilder();
65	        String firstName = owner.getFirstName();
66	        String lastName = owner.getLastName();
67	        if (firstName != null && !firstName.isEmpty()) {
68	            sb.append(Character.toUpperCase(firstName.charAt(0))).append('.');
69	        }
70	        if (lastName != null && !lastName.isEmpty()) {
71	            sb.append(Character.toUpperCase(lastName.charAt(0))).append('.');
72	        }
73	        return sb.toString();
74	    }
75	
76	    /**
77	     * Formats the owner's stored E.164 {@code telephone} for human display: the country code,
78	     * a space, and the national digits grouped in threes separated by spaces, e.g.
79	     * {@code '+61412345678'} becomes {@code '+61 412 345 678'}. The raw {@code telephone} is
80	     * left unchanged in E.164 form.
81	     */
82	    default String telephoneDisplay(Owner owner) {
83	        if (owner == null) {
84	            return null;
85	        }
86	        return TelephoneNormalizer.toDisplay(owner.getTelephone());
87	    }
88	
89	    /**
90	     * Formats the owner's membership number as {@code '<customerCode>-M<YY>'}: the customer
91	     * code, the literal {@code '-M'}, and the last two digits of the registrationDate year.
92	     * Returns {@code null} unless both the customer code and registration date are present.
93	     */
94	    default String membershipNumber(Owner owner) {
95	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
96	            return null;
97	        }
98	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
99	        return owner.getCustomerCode() + "-M" + yy;
100	    }
101	
102	    /**
103	     * Computes the owner's {@code checkDigit}: a single Luhn check digit (0-9) over the digits
104	     * contained in the {@code customerCode}. Returns {@code null} when no customer code is present.
105	     */
106	    default Integer checkDigit(Owner owner) {
107	        if (owner == null || owner.getCustomerCode() == null) {
108	            return null;
109	        }
110	        String code = owner.getCustomerCode();
111	        int sum = 0;
112	        boolean dbl = true;
113	        for (int i = code.length() - 1; i >= 0; i--) {
114	            char c = code.charAt(i);
115	            if (c < '0' || c > '9') {
116	                continue;
117	            }
118	            int d = c - '0';
119	            if (dbl) {
120	                d *= 2;
121	                if (d > 9) {
122	                    d -= 9;
123	                }
124	            }
125	            sum += d;
126	            dbl = !dbl;
127	        }
128	        return (10 - (sum % 10)) % 10;
129	    }
130	
131	    /**
132	     * Computes the owner's membership points. Starts at {@code 0}; adds {@code 2} when an email
133	     * address is present; adds {@code 1} when the owner has no namesakes (namesakeCount is 0);
134	     * adds {@code 2} when the owner belongs to a household of {@code 3} or more members; adds
135	     * {@code 3} when the owner's tenure exceeds 365 days.
136	     */
137	    default Integer membershipPoints(Owner owner) {
138	        if (owner == null) {
139	            return null;
140	        }
141	        int points = 0;
142	        String email = owner.getEmail();
143	        if (email != null && !email.isEmpty()) {
144	            points += 2;
145	        }
146	        Integer namesakeCount = owner.getNamesakeCount();
147	        if (namesakeCount != null && namesakeCount == 0) {
148	            points += 1;
149	        }
150	        Integer householdMemberCount = owner.getHouseholdMemberCount();
151	        if (householdMemberCount != null && householdMemberCount >= 3) {
152	            points += 2;
153	        }
154	        LocalDate registrationDate = owner.getRegistrationDate();
155	        if (registrationDate != null
156	                && ChronoUnit.DAYS.between(registrationDate, LocalDate.now()) > 365) {
157	            points += 3;
158	        }
159	        return points;
160	    }
161	
162	    /**
163	     * Derives the owner's numeric membership level from {@link #membershipPoints(Owner)}: level
164	     * {@code 1} for {@code 0-1} points, level {@code 2} for {@code 2-3} points, level {@code 3}
165	     * for {@code 4-5} points, and level {@code 4} for {@code 6} or more points.
166	     */
167	    default Integer membershipLevel(Owner owner) {
168	        if (owner == null) {
169	            return null;
170	        }
171	        int points = membershipPoints(owner);
172	        if (points <= 1) {
173	            return 1;
174	        }
175	        if (points <= 3) {
176	            return 2;
177	        }
178	        if (points <= 5) {
179	            return 3;
180	        }
181	        return 4;
182	    }
183	
184	    /**
185	     * Derives the owner's locality (region) from the {@code customerCode}, whose form is
186	     * {@code '<REGION>-<HASH8>'}: the locality is the {@code REGION} segment before the first
187	     * hyphen. Returns {@code "UNKNOWN"} when the owner has no customer code yet.
188	     */
189	    default String locality(Owner owner) {
190	        if (owner == null) {
191	            return null;
192	        }
193	        String code = owner.getCustomerCode();
194	        if (code == null) {
195	            return "UNKNOWN";
196	        }
197	        int dash = code.indexOf('-');
198	        return dash >= 0 ? code.substring(0, dash) : code;
199	    }
200	
201	    /**
202	     * Derives the owner's IANA {@code timezone} from its locality/region using the fixed
203	     * region-to-timezone table ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
204	     * {@code QLD -> Australia/Brisbane}). Returns {@code null} when the region is not in the table.
205	     */
206	    default String timezone(Owner owner) {
207	        if (owner == null) {
208	            return null;
209	        }
210	        String region = locality(owner);
211	        return switch (region) {
212	            case "NSW" -> "Australia/Sydney";
213	            case "VIC" -> "Australia/Melbourne";
214	            case "QLD" -> "Australia/Brisbane";
215	            default -> null;
216	        };
217	    }
218	
219	    /**
220	     * Whether the owner carries the bulk-signup warning (more than 80 owners already created
221	     * on its registration day at creation time). A {@code null} stored value is treated as
222	     * {@code false}, so the field is always present in the response.
223	     */
