522	    private <T> T findEntityById(Supplier<T> supplier) {
523	        try {
524	            return supplier.get();
525	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
526	            // Just ignore not found exceptions for Jdbc/Jpa realization
527	            return null;
528	        }
529	    }
